import React, { useEffect, useState } from "react";
import axios from "axios";
// import "../style/dashboard.css";

export default function Dashboard() {
  const [dashboard, setDashboard] = useState({});

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/v1/analytics/dashboard")
      .then((res) => {
        console.log(res.data);
        setDashboard(res.data.data[0]);
      })
      .catch((err) => {
        console.error(err);
      });
  }, []);

  return (
    <div className="container mt-5">

      <h2 className="text-center fw-bold mb-5">
        E-Commerce Dashboard
      </h2>

      <div className="row g-4">

        <div className="col-lg-3 col-md-6">
          <div className="card dashboard-card bg-primary text-white">
            <div className="card-body text-center">
              <h5>Total Customers</h5>
              <h2>{dashboard.total_customers}</h2>
            </div>
          </div>
        </div>

        <div className="col-lg-3 col-md-6">
          <div className="card dashboard-card bg-success text-white">
            <div className="card-body text-center">
              <h5>Total Products</h5>
              <h2>{dashboard.total_products}</h2>
            </div>
          </div>
        </div>

        <div className="col-lg-3 col-md-6">
          <div className="card dashboard-card bg-warning text-dark">
            <div className="card-body text-center">
              <h5>Total Orders</h5>
              <h2>{dashboard.total_orders}</h2>
            </div>
          </div>
        </div>

        <div className="col-lg-3 col-md-6">
          <div className="card dashboard-card bg-danger text-white">
            <div className="card-body text-center">
              <h5>Total Revenue</h5>
              <h2>₹ {dashboard.total_revenue}</h2>
            </div>
          </div>
        </div>

      </div>

    </div>
  );
}
